class Solution:
    def countGoodSubarrays(self, nums: List[int]) -> int:
        ans = 0
        orsegs, mxsegs = [], []
        for r, x in enumerate(nums):
            cur = [[x, r]]
            for v, l in orsegs:
                nv = v | x
                if nv != cur[-1][0]: cur.append([nv, l])
            orsegs = cur
            cur = [[x, r]]
            for v, l in mxsegs:
                nv = v if v > x else x
                if nv != cur[-1][0]: cur.append([nv, l])
            mxsegs = cur
            i = j = 0
            while i < len(orsegs) and j < len(mxsegs):
                lo = max(orsegs[i][1], mxsegs[j][1])
                ei = orsegs[i+1][1] - 1 if i + 1 < len(orsegs) else r
                ej = mxsegs[j+1][1] - 1 if j + 1 < len(mxsegs) else r
                hi = min(ei, ej)
                if orsegs[i][0] == mxsegs[j][0] and hi >= lo:
                    ans += hi - lo + 1
                if ei <= ej: i += 1
                else: j += 1
        return ans

