class Solution {
public:
    long long countGoodSubarrays(vector<int>& nums) {
        long long ans = 0;
        vector<pair<long long,int>> orsegs, mxsegs;
        for (int r = 0; r < (int)nums.size(); r++) {
            long long x = nums[r];
            vector<pair<long long,int>> cur{{x, r}};
            for (auto& [v, l] : orsegs) {
                long long nv = v | x;
                if (nv != cur.back().first) cur.push_back({nv, l});
            }
            orsegs = cur;
            cur.assign({{x, r}});
            for (auto& [v, l] : mxsegs) {
                long long nv = max(v, x);
                if (nv != cur.back().first) cur.push_back({nv, l});
            }
            mxsegs = cur;
            int i = 0, j = 0;
            while (i < (int)orsegs.size() && j < (int)mxsegs.size()) {
                int lo = max(orsegs[i].second, mxsegs[j].second);
                int ei = i + 1 < (int)orsegs.size() ? orsegs[i+1].second - 1 : r;
                int ej = j + 1 < (int)mxsegs.size() ? mxsegs[j+1].second - 1 : r;
                int hi = min(ei, ej);
                if (orsegs[i].first == mxsegs[j].first && hi >= lo)
                    ans += hi - lo + 1;
                if (ei <= ej) i++; else j++;
            }
        }
        return ans;
    }
};

