class Solution {
    public long countGoodSubarrays(int[] nums) {
        long ans = 0;
        List<long[]> orsegs = new ArrayList<>(), mxsegs = new ArrayList<>();
        for (int r = 0; r < nums.length; r++) {
            long x = nums[r];
            List<long[]> cur = new ArrayList<>();
            cur.add(new long[]{x, r});
            for (long[] sg : orsegs) {
                long nv = sg[0] | x;
                if (nv != cur.get(cur.size()-1)[0]) cur.add(new long[]{nv, sg[1]});
            }
            orsegs = cur;
            cur = new ArrayList<>();
            cur.add(new long[]{x, r});
            for (long[] sg : mxsegs) {
                long nv = Math.max(sg[0], x);
                if (nv != cur.get(cur.size()-1)[0]) cur.add(new long[]{nv, sg[1]});
            }
            mxsegs = cur;
            int i = 0, j = 0;
            while (i < orsegs.size() && j < mxsegs.size()) {
                long lo = Math.max(orsegs.get(i)[1], mxsegs.get(j)[1]);
                long ei = i + 1 < orsegs.size() ? orsegs.get(i+1)[1] - 1 : r;
                long ej = j + 1 < mxsegs.size() ? mxsegs.get(j+1)[1] - 1 : r;
                long hi = Math.min(ei, ej);
                if (orsegs.get(i)[0] == mxsegs.get(j)[0] && hi >= lo)
                    ans += hi - lo + 1;
                if (ei <= ej) i++; else j++;
            }
        }
        return ans;
    }
}

