        cur = [[x, r]];
        for (const [v, l] of mxsegs) {
            const nv = Math.max(v, x);
            if (nv !== cur[cur.length-1][0]) cur.push([nv, l]);
        }
        mxsegs = cur;
        let i = 0, j = 0;
        while (i < orsegs.length && j < mxsegs.length) {
            const lo = Math.max(orsegs[i][1], mxsegs[j][1]);
